-- 255: Meta breakdowns carry the funnel steps the why tool decomposes (Josh 2026-11-13: find what CHANGED in placement / device / platform / age / gender / country).
--   public.meta_breakdown_daily gets nullable add_to_cart and initiate_checkout (Meta-reported, omni > plain > pixel like purchases; NULL = not pulled yet, never 0). The pull fills them with
--   the rest of the row; rows pulled before this migration are filled by `python -m etl.meta_breakdowns --fill-funnel --since D` (UPDATE of these two columns of existing rows only).
--   analytics.meta_breakdown_daily gains add_to_carts and initiated_checkouts at the END (CREATE OR REPLACE VIEW can only append) and three more breakdown names:
--   impression_device, placement (publisher_platform|platform_position) and placement_device (publisher_platform|platform_position|impression_device). Idempotent.
-- Everything above the "comments" marker is hand-written DDL; everything below it is GENERATED by `python scripts/gen_schema_doc.py --emit-migration 255` from docs/schema/descriptions.py.
ALTER TABLE public.meta_breakdown_daily ADD COLUMN IF NOT EXISTS add_to_cart numeric(12,2);
ALTER TABLE public.meta_breakdown_daily ADD COLUMN IF NOT EXISTS initiate_checkout numeric(12,2);

CREATE OR REPLACE VIEW analytics.meta_breakdown_daily AS
SELECT d.day,
       CASE d.account_id WHEN 'act_1671338033619223' THEN 'Lonvera Main' WHEN 'act_1543579384022317' THEN 'Lonvera BackUp' ELSE d.account_id END AS account,
       d.campaign_id,
       d.adset_id,
       CASE WHEN d.level = 'ad' THEN d.entity_id END AS ad_id,
       m.breakdown,
       CASE WHEN m.breakdown = 'age_gender' THEN concat_ws('|', d.dim1, d.dim2)
            WHEN m.breakdown IN ('placement', 'placement_device') THEN concat_ws('|', d.dim1, d.dim2, d.dim3)
            ELSE d.dim1 END AS value,
       d.spend,
       d.impressions,
       d.reach,
       d.inline_link_clicks AS link_clicks,
       d.unique_outbound_clicks,
       d.purchases,
       d.purchase_value,
       d.add_to_cart AS add_to_carts,
       d.initiate_checkout AS initiated_checkouts
FROM public.meta_breakdown_daily d
JOIN (VALUES ('user_segment_key', 'audience_segment'), ('age', 'age'), ('gender', 'gender'), ('age,gender', 'age_gender'), ('country', 'country'), ('region', 'region'),
             ('publisher_platform', 'publisher_platform'), ('platform_position', 'platform_position'), ('device_platform', 'device_platform'),
             ('hourly_stats_aggregated_by_advertiser_time_zone', 'hourly'), ('impression_device', 'impression_device'),
             ('publisher_platform,platform_position', 'placement'), ('publisher_platform,platform_position,impression_device', 'placement_device')) m(set_name, breakdown) ON m.set_name = d.breakdown_set;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'analytics_reader') THEN
    GRANT SELECT ON analytics.meta_breakdown_daily TO analytics_reader;
  END IF;
END $$;

-- ---------------------------------------------------------------- comments
COMMENT ON TABLE public.meta_breakdown_daily IS 'Meta Ads results split by one breakdown set (age, gender, country, region, dma, placement, device, hour of day, creative asset ...), pulled at AD grain from the Insights API for both ad accounts. Partitioned by month on day. Grain: one row per day x ad account x level (ad; campaign or account only for a set Meta refused at ad level) x entity x breakdown set x dimension values. Source: Meta Marketing API Insights (read only), etl.meta_breakdowns. Refresh: every 2 hours by the dedicated `breakdowns` service: the backfill (newest 30-day window first) until finished, then the trailing 7 days once a day. Coverage: see meta_breakdown_coverage for the first and last day and the level per set. Caveats: purchases and purchase_value are Meta-reported (they count returning customers, not Upstack new customers). | Reach and unique outbound clicks are per row (one ad, one day, one dimension value): never sum them across days, ads or sets. | Action breakdown sets (action_device, action_destination ...) split only purchases and purchase_value; their spend, impressions and click columns are NULL. | Rows of different breakdown sets are different cuts of the same spend: never add across sets. | Meta can return a row for a day with purchases but no spend (view-through), so keep rows with zero spend. | Up to three dimension values per row sit in dim1, dim2, dim3 in the order of the names in breakdown_set (age,gender: dim1 = age, dim2 = gender); asset breakdowns store the JSON text Meta returned.';
COMMENT ON COLUMN public.meta_breakdown_daily.day IS 'Calendar day as returned by Meta (each ad account buckets days in its own time zone: Lonvera Main Pacific, Lonvera BackUp Eastern).';
COMMENT ON COLUMN public.meta_breakdown_daily.account_id IS 'Meta ad account id with the act_ prefix.';
COMMENT ON COLUMN public.meta_breakdown_daily.level IS 'Grain of the entity: ad (the default for every set), campaign or account (only for a set Meta refused at the finer level).';
COMMENT ON COLUMN public.meta_breakdown_daily.entity_id IS 'Ad id, campaign id or ad account id, depending on level.';
COMMENT ON COLUMN public.meta_breakdown_daily.campaign_id IS 'Campaign of the entity (NULL at account level).';
COMMENT ON COLUMN public.meta_breakdown_daily.adset_id IS 'Ad set of the entity (ad level only).';
COMMENT ON COLUMN public.meta_breakdown_daily.breakdown_set IS 'Comma-separated breakdown names that were requested together, for example age,gender or publisher_platform,platform_position,impression_device.';
COMMENT ON COLUMN public.meta_breakdown_daily.dim1 IS 'Value of the first name in breakdown_set (text).';
COMMENT ON COLUMN public.meta_breakdown_daily.dim2 IS 'Value of the second name in breakdown_set, NULL when the set has one name.';
COMMENT ON COLUMN public.meta_breakdown_daily.dim3 IS 'Value of the third name in breakdown_set, NULL when the set has fewer than three.';
COMMENT ON COLUMN public.meta_breakdown_daily.dims_key IS 'Stable text form of the dimension values (names sorted, name=value joined with a vertical bar, percent-escaped); any length. Not indexed: the primary key uses dims_hash.';
COMMENT ON COLUMN public.meta_breakdown_daily.spend IS 'Meta spend in account currency (US dollars). NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.impressions IS 'Meta impressions. NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.reach IS 'Accounts reached on that day within the row. Not additive across days, ads or sets. NULL for action breakdown sets or when Meta would not return it with the breakdown.';
COMMENT ON COLUMN public.meta_breakdown_daily.clicks IS 'All clicks (Meta clicks field), not only link clicks. NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.inline_link_clicks IS 'Link clicks (Meta inline_link_clicks). NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.outbound_clicks IS 'Outbound clicks (clicks that left Meta; Meta outbound_clicks, action type outbound_click). NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.unique_outbound_clicks IS 'Unique outbound clicks within the row (Meta unique_outbound_clicks). Not additive across days or ads. NULL for action breakdown sets.';
COMMENT ON COLUMN public.meta_breakdown_daily.purchases IS 'Meta-reported purchases (omni_purchase, else purchase, else pixel purchase), same rule as ad_daily.';
COMMENT ON COLUMN public.meta_breakdown_daily.purchase_value IS 'Meta-reported purchase value (same action type rule), gross dollars.';
COMMENT ON COLUMN public.meta_breakdown_daily.pulled_at IS 'When this row was last written by the pull.';
COMMENT ON COLUMN public.meta_breakdown_daily.dims_hash IS 'md5 of dims_key (generated column), the fixed-size stand-in for dims_key in the primary key so very long values (ad copy assets) can be indexed.';
COMMENT ON COLUMN public.meta_breakdown_daily.add_to_cart IS 'Meta-reported adds to cart (omni_add_to_cart, else add_to_cart, else pixel add to cart, same rule as ad_daily). NULL for action breakdown sets and for rows not filled yet (never 0); history is filled by etl.meta_breakdowns --fill-funnel.';
COMMENT ON COLUMN public.meta_breakdown_daily.initiate_checkout IS 'Meta-reported initiated checkouts (omni_initiated_checkout, else initiate_checkout, else pixel). NULL for action breakdown sets and for rows not filled yet.';
COMMENT ON TABLE public.meta_breakdown_coverage IS 'What the breakdown pull holds per breakdown set and level: whether Meta accepted the request, the first and last day held, the row count and the last error. Grain: one row per breakdown set x level. Source: etl.meta_breakdowns (written after every window). Refresh: nightly and after every backfill window. Coverage: from the first run. Caveats: A set Meta refuses at ad level gets a status unsupported row at level ad (with the reason in last_error) and is pulled at campaign, then account level; each level has its own row. | status unsupported is asked again every 14 days. status error means a transient or unexpected failure, so the set may have gaps. | first_day, last_day and rows are read from meta_breakdown_daily after each window, so during a backfill first_day moves back window by window.';
COMMENT ON COLUMN public.meta_breakdown_coverage.breakdown_set IS 'Breakdown set name, as in meta_breakdown_daily.breakdown_set.';
COMMENT ON COLUMN public.meta_breakdown_coverage.level IS 'Level the set was requested at: ad, campaign or account.';
COMMENT ON COLUMN public.meta_breakdown_coverage.status IS 'ok = Meta accepted it and rows are held; unsupported = Meta refused the request at this level; error = failed for another reason (see last_error).';
COMMENT ON COLUMN public.meta_breakdown_coverage.first_day IS 'Earliest day held in meta_breakdown_daily for this set and level.';
COMMENT ON COLUMN public.meta_breakdown_coverage.last_day IS 'Latest day held in meta_breakdown_daily for this set and level.';
COMMENT ON COLUMN public.meta_breakdown_coverage.last_error IS 'Scrubbed text of the last refusal or failure; NULL when the last check was clean.';
COMMENT ON COLUMN public.meta_breakdown_coverage.rows IS 'Rows held in meta_breakdown_daily for this set and level.';
COMMENT ON COLUMN public.meta_breakdown_coverage.checked_at IS 'When the set was last requested.';
COMMENT ON TABLE public.meta_breakdown_progress IS 'Resume bookkeeping of the breakdown backfill: one row per finished window of one breakdown set at one level for one ad account, so running the same backfill again skips what is done. Grain: one row per breakdown set x level x ad account x window. Source: etl.meta_breakdowns (backfill and --auto mode; the plain trailing-days pull does not write it). Refresh: written as each window x set finishes. Coverage: backfill windows and the three bookkeeping rows. Caveats: A window is skipped on a rerun when a recorded window covers it. The backfill anchor is stored here on the first --auto run, so a resume after midnight needs no arguments. | Three bookkeeping rows have breakdown_set __anchor__ (window_start = oldest day, window_end = the backfill''s --until day, rows = max days), __backfill_done__ (the backfill finished) and __caught_up__ (window_end = the last day the daily catch-up covered); level and account_id are ''-''. | Safe to delete (or run with --restart): the next backfill simply starts over and pulls again (upserts).';
COMMENT ON COLUMN public.meta_breakdown_progress.breakdown_set IS 'Breakdown set name.';
COMMENT ON COLUMN public.meta_breakdown_progress.level IS 'Level the window was pulled at.';
COMMENT ON COLUMN public.meta_breakdown_progress.account_id IS 'Meta ad account id.';
COMMENT ON COLUMN public.meta_breakdown_progress.window_start IS 'First day of the finished window (the oldest day for the __anchor__ row).';
COMMENT ON COLUMN public.meta_breakdown_progress.window_end IS 'Last day of the finished window.';
COMMENT ON COLUMN public.meta_breakdown_progress.rows IS 'Rows written for the window (both accounts are separate rows).';
COMMENT ON COLUMN public.meta_breakdown_progress.done_at IS 'When the window finished.';
COMMENT ON VIEW analytics.meta_breakdown_daily IS 'Meta results split by thirteen everyday breakdowns (audience segment, age, gender, age x gender, country, region, publisher platform, platform position, impression device, device platform, placement, placement x device, hour of day), one row per day x ad x breakdown x value. Meta-reported numbers, including adds to cart and initiated checkouts (the funnel the why tool decomposes by segment). Grain: one row per (day, account, ad_id, breakdown, value); NO aggregation above ad. Source: public.meta_breakdown_daily (etl.meta_breakdowns, Meta Insights API) joined to the thirteen breakdown names. Refresh: nightly, trailing 7 days re-pulled; older windows come from the backfill (newest first). Coverage: first and last day per breakdown: min(day) / max(day) over this view (a backfill moves first_day back window by window, up to 365 days; a breakdown Meta only serves for a shorter period stops earlier); ad_id and adset_id are NULL only where Meta refused a breakdown at ad level. Caveats: Every one of the ten breakdowns is requested at AD level; ad_id and adset_id are NULL only for a breakdown Meta refused at ad level (then campaign_id is set and ad_id and adset_id are NULL; at account level campaign_id is NULL too). Query this view with ad_id IS NOT NULL (or read public.meta_breakdown_coverage: status and level per breakdown) to see which breakdowns have ad-level rows. | purchases and purchase_value are Meta-reported (count returning customers); they are not Upstack new customers and must not be mixed with them in one ratio. | reach and unique_outbound_clicks are per row (one ad, one day, one value): never sum them across days, ads or values. spend, impressions, link_clicks, purchases and purchase_value are additive within one breakdown. | Different breakdowns are different cuts of the same spend: sum within one breakdown only, never across breakdowns. | value for age_gender is ''age|gender'' (for example ''25-34|female''); hourly values are Meta''s advertiser-time-zone hour buckets (''00:00:00 - 00:59:59''). | Meta can return purchases for a day with no spend (view-through): keep those rows. | add_to_carts and initiated_checkouts are NULL (not 0) for rows pulled before 2026-11-13 until etl.meta_breakdowns --fill-funnel has filled them; sum them only over days where they are not NULL. placement values are ''publisher|position'', placement_device ''publisher|position|device''. | The why tool reads this view to split a move in CPM, click rate, cost per click, link click to add to cart, add to cart to purchase and cost per purchase into segment mix and within-segment rate shifts (shift-share), against a same-weekday control and the segment''s own daily noise.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.day IS 'Calendar day as returned by Meta (Lonvera Main Pacific, Lonvera BackUp Eastern).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.campaign_id IS 'Meta campaign id (NULL only for a breakdown held at account level).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.adset_id IS 'Meta ad set id (NULL only for a breakdown Meta refused at ad level).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.ad_id IS 'Meta ad id (NULL only for a breakdown Meta refused at ad level: campaign or account rows).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.breakdown IS 'audience_segment (from user_segment_key) | age | gender | age_gender | country | region | publisher_platform | platform_position | impression_device | device_platform | placement | placement_device | hourly (advertiser time zone). All are requested at ad level.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.value IS 'The text value of the breakdown (''25-34'', ''female'', ''US'', ''facebook'', ''25-34|female'' for age_gender, an hour bucket for hourly).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.reach IS 'Accounts reached on the day within the row (not additive; NULL when Meta would not return it with the breakdown).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.link_clicks IS 'Meta link clicks (inline_link_clicks).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.unique_outbound_clicks IS 'Unique outbound clicks within the row (not additive).';
COMMENT ON COLUMN analytics.meta_breakdown_daily.purchases IS 'Meta-reported purchases.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.purchase_value IS 'Meta-reported purchase value, dollars.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.add_to_carts IS 'Meta-reported adds to cart (omni_add_to_cart, else add_to_cart, else pixel). NULL for rows not filled yet, never 0.';
COMMENT ON COLUMN analytics.meta_breakdown_daily.initiated_checkouts IS 'Meta-reported initiated checkouts (omni_initiated_checkout, else initiate_checkout, else pixel). NULL for rows not filled yet.';
